const n=[{id:"wf-wedding",title:"Wedding Timeline",timeline:["Konsep Acara Pernikahan / Awal → H-90","Pemilihan Vendor / Detail → H-60","Persiapan Final (Technical Meeting) → H-14","Pelaksanaan Acara Pernikahan → Hari H","Penyelesaian / Review Akhir → H+7","Serah Terima Dokumentasi / Laporan → H+30"]},{id:"wf-small-event",title:"Event / Acara Pernikahan Kecil Timeline",timeline:["Konsep / Kesepakatan Awal → H-30","Persiapan Final → H-7","Pelaksanaan Acara Pernikahan → Hari H","Penyelesaian Layanan / Laporan → H+14"]}],l=a=>{if(a?.workflows?.length)return a.workflows;const e=[];return a?.weddingWorkflow?.title&&e.push({id:"wf-wedding",title:a.weddingWorkflow.title,timeline:a.weddingWorkflow.timeline||[]}),a?.smallEventWorkflow?.title&&e.push({id:"wf-small-event",title:a.smallEventWorkflow.title,timeline:a.smallEventWorkflow.timeline||[]}),e.length>0?e:n},i=[{id:"pt-booking",title:"Ketentuan Pemesanan & Pembayaran DP",items:["Booking paket dinyatakan sah setelah pembayaran Down Payment (DP) minimal 30%.","Tanggal acara hanya akan di-lock setelah bukti transfer DP diverifikasi.","Pelunasan total biaya paket dilakukan selambat-lambatnya H-7 sebelum hari pelaksanaan acara.","Pembayaran hanya sah melalui rekening resmi vendor yang tertera di dokumen invoice."]},{id:"pt-reschedule",title:"Perubahan Jadwal & Penyesuaian Paket",items:["Permintaan penyesuaian jadwal (reschedule) wajib disampaikan minimal H-30 sebelum hari acara.","Perubahan tanggal tunduk pada ketersediaan jadwal tim vendor pada tanggal yang baru.","Upgrade paket atau penambahan add-on dapat dilakukan kapan saja sebelum hari H."]},{id:"pt-execution",title:"Pelaksanaan & Penyerahan Hasil Layanan",items:["Tim vendor akan tiba di lokasi acara selambat-lambatnya 2 jam sebelum rundown dimulai.","Preview hasil layanan (teaser / highlight foto & video) dikirimkan maksimal H+7 acara.","Seluruh hasil final (full album / Google Drive / video edit) diserahkan maksimal H+30 acara."]},{id:"pt-cancellation",title:"Pembatalan & Force Majeure",items:["Pembatalan sepihak dari pihak klien menyebabkan DP hangus dan tidak dapat dikembalikan.","Keadaan force majeure (bencana alam, huru-hara, regulasi darurat) diselesaikan secara musyawarah mufakat."]}],t=a=>a&&a.length>0?a:i;export{n as D,i as a,t as b,l as g};
